  stats2.matchesPlayed = row.played || 0;
  stats2.wins = row.won || 0;
  stats2.draws = row.drawn || 0;
  stats2.losses = row.lost || 0;
  stats2.goalsScored = row.goalsFor || 0;
  stats2.goalsConceded = row.goalsAgainst || 0;
